  const start=document.getElementById('start');
  if(start && !document.getElementById('hp-booked-live')){
    const sec=document.createElement('div');sec.id='hp-booked-live';sec.className='final-extra searchable';sec.dataset.search='harry potter booked 17 august golden tours bulleid way 12:45 13:00 two adults premium seating';
    sec.innerHTML=`<div class="fx-k">17 августа · уже куплено</div><h2 class="fx-title">Harry Potter Studio Tour — 2 билета Golden Tours</h2><div class="fx-grid"><article class="fx-card wide searchable"><span class="fx-bought">✓ 2 билета куплены</span><h3>Понедельник, 17 августа 2026</h3><p><strong>Продукт:</strong> Warner Bros. Studio Tour London – The Making of Harry Potter with Return Transport, Premium Seating.</p><p><strong>Meeting time:</strong> 12:45. <strong>Автобус:</strong> 13:00. <strong>Точка:</strong> <strong>Stop 1, Bulleid Way, London SW1W 9SR</strong>. Это Golden Tours departure point возле Victoria, <strong>не Victoria Coach Station</strong>.</p><p><strong>Order reference:</strong> W5V6BZ85. На посадке нужно показать e-ticket; после посадки Golden Tours выдаёт Studio entry tickets.</p><div class="fx-note"><strong>План из Windsor:</strong> я бы целилась приехать к Victoria/Bulleid Way примерно к 12:10–12:20, а не к 12:45. Из Windsor закладывайте минимум 1 ч 20–1 ч 40 мин на поезд + пересадку/пеший участок и отдельный запас. Практичный вариант — Windsor & Eton Central → Slough → London Paddington → далее Elizabeth/Circle/District/такси до Victoria и пешком к Bulleid Way. Утром 17 августа обязательно проверить National Rail/Citymapper на живые изменения.</div><div class="fx-actions"><a href="https://www.google.com/maps/dir/?api=1&origin=Windsor+%26+Eton+Central&destination=Bulleid+Way,+London+SW1W+9SR&travelmode=transit" target="_blank" rel="noopener">Windsor → Bulleid Way</a><a href="https://www.google.com/maps/search/?api=1&query=Golden+Tours+Stop+1+Bulleid+Way+London+SW1W+9SR" target="_blank" rel="noopener">Точная точка посадки</a></div></article></div>`;
    const timeline=start.querySelector('.timeline'); if(timeline) timeline.insertAdjacentElement('afterend',sec); else start.appendChild(sec);
  }
